# Let s = sin(x). The product of the two shifted sines follows from
# (a-b)(a+b) = a^2-b^2, with sin(60°)=sqrt(3)/2 and cos(60°)=1/2:
# sin(60°-x) sin(60°+x) = (3/4)cos²(x) - (1/4)sin²(x).
# Using cos²(x)=1-s² gives the exact polynomial below.
product_coefficients = {
    1: 4 * Fraction(3, 4),
    3: -4,
}

# Independently derive sin(3x) from sin(2x+x), using
# sin(2x)=2sin(x)cos(x), cos(2x)=1-2sin²(x), and cos²(x)=1-sin²(x).
triple_angle_coefficients = {
    1: 2 + 1,
    3: -2 - 2,
}

if product_coefficients != triple_angle_coefficients:
    print(json.dumps({
        "final_answer": "UNSUPPORTED",
        "evidence": "Exact coefficient comparison did not establish an identity."
    }))
else:
    print(json.dumps({
        "final_answer": "sin(3x)",
        "evidence": "Both exact polynomials in sin(x) have coefficients "
