# Polynomials in s = sin(x), stored as coefficients in ascending powers.
def add(a, b):
    out = [F(0)] * max(len(a), len(b))
    for i, v in enumerate(a):
        out[i] += v
    for i, v in enumerate(b):
        out[i] += v
    return trim(out)

def scale(a, k):
    return trim([F(k) * v for v in a])

def multiply(a, b):
    out = [F(0)] * (len(a) + len(b) - 1)
    for i, u in enumerate(a):
        for j, v in enumerate(b):
            out[i + j] += u * v
    return trim(out)

def trim(a):
    while len(a) > 1 and a[-1] == 0:
        a.pop()
    return a

