from fractions import Fraction
import json

# The original equation, with t = x + y, gives
# f(x+t) = g(x)f(t) - x, where g(x) = f(x) + x.
# Setting t=0 yields (1-f(0))(f(x)+x)=0. If f(0) != 1,
# this forces f(x)=-x, which contradicts the transformed equation
# at x=t=1. Thus f(0)=1.
f0 = Fraction(1)

# Compose the transformed equation along x, then y, and compare with
# applying it once with x+y. The difference is
# (g(x)g(y)-g(x+y))f(z) + y(1-g(x)) = 0.
# Injectivity makes f nonconstant, so both coefficients must vanish.
# Taking y=1 in the constant term gives g(x)=1 for every x.
g_value = Fraction(1)

# Now use t=0 in the transformed equation: f(x)=f(0)-x.
slope = -g_value
intercept = f0

# Exact polynomial verification of the original equation for the result.
def add(a, b):
    out = dict(a)
    for k, v in b.items():
        out[k] = out.get(k, Fraction(0)) + v
        if out[k] == 0:
            del out[k]
    return out

def neg(a):
    return {k: -v for k, v in a.items()}

def mul(a, b):
    out = {}
    for (i, j), av in a.items():
        for (k, ell), bv in b.items():
            key = (i + k, j + ell)
            out[key] = out.get(key, Fraction(0)) + av * bv
    return {k: v for k, v in out.items() if v != 0}

x = {(1, 0): Fraction(1)}
y = {(0, 1): Fraction(1)}
one = {(0, 0): Fraction(1)}

def f_poly(p):
    return add({(0, 0): intercept}, {k: slope * v for k, v in p.items()})

fx = f_poly(x)
fxy = f_poly(add(x, y))
f2xy = f_poly(add({(1, 0): Fraction(2)}, y))
lhs = mul(fx, fxy)
rhs = add(f2xy, add(neg(mul(x, fxy)), x))
assert add(lhs, neg(rhs)) == {}
assert slope != 0  # Hence the resulting affine function is injective.

answer = f"f(x) = {intercept} - x"
print(json.dumps({
    "final_answer": answer,
    "evidence": "Reparameterization and associativity force g(x)=1; t=0 then gives f(x)=f(0)-x with f(0)=1. Exact polynomial substitution verifies the original equation, and slope -1 ensures injectivity."
}, separators=(",", ":")))
