from fractions import Fraction
from itertools import permutations

# A polynomial is a dict mapping (power_of_x, power_of_s, power_of_c)
# to an exact coefficient.
def add(a, b):
    result = a.copy()
    for monomial, coefficient in b.items():
        result[monomial] = result.get(monomial, Fraction(0)) + coefficient
        if result[monomial] == 0:
            del result[monomial]
    return result

def scale(poly, factor):
    return {m: factor * coefficient for m, coefficient in poly.items()
            if factor * coefficient != 0}

def multiply(a, b):
    result = {}
    for (ax, ass, ac), av in a.items():
        for (bx, bs, bc), bv in b.items():
            monomial = (ax + bx, ass + bs, ac + bc)
            result[monomial] = result.get(monomial, Fraction(0)) + av * bv
    return {m: coefficient for m, coefficient in result.items()
            if coefficient != 0}

def constant(value):
    return {(0, 0, 0): Fraction(value)}

x = {(1, 0, 0): Fraction(1)}
s = {(0, 1, 0): Fraction(1)}
c = {(0, 0, 1): Fraction(1)}
one = constant(1)

matrix = [
    [x, s, c],
    [scale(s, -1), scale(x, -1), one],
    [c, one, x],
]

determinant = {}
for perm in permutations(range(3)):
    inversions = sum(perm[i] > perm[j]
                     for i in range(3) for j in range(i + 1, 3))
    product = one
    for row in range(3):
        product = multiply(product, matrix[row][perm[row]])
    determinant = add(determinant, scale(product, -1 if inversions % 2 else 1))

# Reduce using the exact identity cos(theta)^2 = 1 - sin(theta)^2.
reduced = {}
for (xp, sp, cp), coefficient in determinant.items():
    pending = {(xp, sp, cp): coefficient}
    while pending:
        (a, b, d), coeff = pending.popitem()
        if d >= 2:
            for monomial, factor in (((a, b, d - 2), 1),
                                     ((a, b + 2, d - 2), -1)):
                pending[monomial] = pending.get(monomial, Fraction(0)) + coeff * factor
        elif coeff:
            reduced[(a, b, d)] = reduced.get((a, b, d), Fraction(0)) + coeff
reduced = {m: coeff for m, coeff in reduced.items() if coeff}

expected = {(3, 0, 0): Fraction(-1)}
assert reduced == expected
print("Determinant using sin(theta)^2 + cos(theta)^2 = 1: -x^3")

# Exact counterexample to the submitted answer: x=1, sin(theta)=0, cos(theta)=1.
values = [[Fraction(1), Fraction(0), Fraction(1)],
          [Fraction(0), Fraction(-1), Fraction(1)],
          [Fraction(1), Fraction(1), Fraction(1)]]
numeric_det = (
    values[0][0] * (values[1][1] * values[2][2] - values[1][2] * values[2][1])
    - values[0][1] * (values[1][0] * values[2][2] - values[1][2] * values[2][0])
    + values[0][2] * (values[1][0] * values[2][1] - values[1][1] * values[2][0])
)
print(f"Counterexample x=1, theta=0: determinant = {numeric_det}, not 0")
print("CHECK FAIL")
