import json

# Polynomials in n, stored as ascending coefficient lists.
def trim(p):
    p = list(p)
    while len(p) > 1 and p[-1] == 0:
        p.pop()
    return p

def add(a, b):
    out = [0] * max(len(a), len(b))
    for i, v in enumerate(a):
        out[i] += v
    for i, v in enumerate(b):
        out[i] += v
    return trim(out)

def neg(a):
    return trim([-v for v in a])

def sub(a, b):
    return add(a, neg(b))

def mul(a, b):
    out = [0] * (len(a) + len(b) - 1)
    for i, x in enumerate(a):
        for j, y in enumerate(b):
            out[i + j] += x * y
    return trim(out)

def rat_sub(a, b):
    # Rational functions represented as (numerator, denominator).
    return (sub(mul(a[0], b[1]), mul(b[0], a[1])),
            mul(a[1], b[1]))

def rat_mul(a, b):
    return (mul(a[0], b[0]), mul(a[1], b[1]))

def equals_integer(r, value):
    return r[0] == mul([value], r[1])

n = [0, 1]
one = [1]
n_squared = mul(n, n)

# From k^2*C(n,k) = n(n-1)*C(n-2,k-2) + n*C(n-1,k-1),
# followed by the binomial theorem:
# p_n(x) = ((n^2-n)/n^2)x^2 + (n/n^2)x.
p_x = (n, n_squared)
p_x2 = (sub(n_squared, n), n_squared)

# Compute the coefficients of n*(p_n(x)-x^2).
limit_x = rat_mul((n, one), p_x)
limit_x2 = rat_mul((n, one), rat_sub(p_x2, (one, one)))

assert equals_integer(limit_x, 1)
assert equals_integer(limit_x2, -1)

print(json.dumps({
    "final_answer": "x(1-x)",
    "evidence": "The binomial moment identity gives p_n(x)=((n-1)/n)x^2+x/n for n>=1; exact coefficient arithmetic gives n(p_n(x)-x^2)=x-x^2 for every n>=1. Thus the limit is x(1-x) (in particular for x in [0,1])."
}))
