import json
from fractions import Fraction
from math import isqrt


def clean(poly):
    return {monomial: Fraction(coefficient)
            for monomial, coefficient in poly.items() if coefficient}


def add(p, q):
    result = dict(p)
    for monomial, coefficient in q.items():
        result[monomial] = result.get(monomial, Fraction(0)) + coefficient
    return clean(result)


def scale(p, coefficient):
    return clean({m: coefficient * c for m, c in p.items()})


def multiply(p, q):
    result = {}
    for (a1, b1), c1 in p.items():
        for (a2, b2), c2 in q.items():
            monomial = (a1 + a2, b1 + b2)
            result[monomial] = result.get(monomial, Fraction(0)) + c1 * c2
    return clean(result)


def power(p, n):
    result = {(0, 0): Fraction(1)}
    for _ in range(n):
        result = multiply(result, p)
    return result


A = {(1, 0): Fraction(1)}
B = {(0, 1): Fraction(1)}
A_MINUS_B = add(A, scale(B, Fraction(-1)))


def factor_difference_of_powers(x, y, n):
    """Return factors whose product is x**n - y**n."""
    if n == 1:
        return [add(x, scale(y, Fraction(-1)))]
    if n % 2 == 0:
        half = n // 2
        return (factor_difference_of_powers(x, y, half)
                + [add(power(x, half), power(y, half))])
    geometric_sum = {}
    for k in range(n):
        term = multiply(power(x, n - 1 - k), power(y, k))
        geometric_sum = add(geometric_sum, term)
    return [add(x, scale(y, Fraction(-1))), geometric_sum]


first_factors = factor_difference_of_powers(A, B, 4)
first_target = add(power(A, 4), scale(power(B, 4), Fraction(-1)))
first_product = {(0, 0): Fraction(1)}
for factor in first_factors:
    first_product = multiply(first_product, factor)
assert first_product == first_target


# Set x = sqrt(a), y = sqrt(b), and construct the polynomial for the
# second expression. Derive a linear square root from its coefficients.
X = {(1, 0): Fraction(1)}
Y = {(0, 1): Fraction(1)}
second_target = add(add(power(X, 2), power(Y, 2)),
                    scale(multiply(X, Y), Fraction(-2)))

x2_coefficient = second_target.get((2, 0), Fraction(0))
xy_coefficient = second_target.get((1, 1), Fraction(0))
assert x2_coefficient.denominator == 1 and x2_coefficient >= 0
u = Fraction(isqrt(x2_coefficient.numerator))
assert u * u == x2_coefficient and u != 0
v = xy_coefficient / (2 * u)
square_root = add(scale(X, u), scale(Y, v))
assert multiply(square_root, square_root) == second_target
assert square_root.get((0, 2), Fraction(0)) ** 2 == 1


def render(poly, variables):
    terms = []
    ordered = sorted(poly.items(), key=lambda item: item[0], reverse=True)
    for (ex, ey), coefficient in ordered:
        if coefficient == 0:
            continue
        magnitude = abs(coefficient)
        factors = []
        for exponent, name in ((ex, variables[0]), (ey, variables[1])):
            if exponent:
                factors.append(name if exponent == 1 else f"{name}^{exponent}")
        monomial = " ".join(factors)
        if not monomial or magnitude != 1:
            coefficient_text = (str(magnitude.numerator)
                                if magnitude.denominator == 1
                                else f"{magnitude.numerator}/{magnitude.denominator}")
            monomial = (coefficient_text + (" " + monomial if monomial else ""))
        if not terms:
            terms.append(("-" if coefficient < 0 else "") + monomial)
        else:
            terms.append((" - " if coefficient < 0 else " + ") + monomial)
    return "".join(terms) or "0"


first_factor_text = [render(factor, ("a", "b")) for factor in first_factors]
root_text = render(square_root, ("√a", "√b"))

answer = (
    f"a^4 - b^4 = {' '.join(f'({factor})' for factor in first_factor_text)}; "
    f"a + b - 2√(ab) = ({root_text})^2"
)
print(json.dumps({
