import json

def add(a, b, factor=1):
    result = a.copy()
    for key, value in b.items():
        result[key] = result.get(key, Fraction(0)) + factor * value
        if result[key] == 0:
            del result[key]
    return result

def multiply(a, b):
    result = {}
    for (t1, b1, c1), v1 in a.items():
        for (t2, b2, c2), v2 in b.items():
            key = (t1 + t2, b1 + b2, c1 + c2)
            result[key] = result.get(key, Fraction(0)) + v1 * v2
