from fractions import Fraction
import json

# Balance: a NaHSO3 + b HCl -> c NaCl + d SO2 + e H2O.
# The givens fix a = 1 and e = 1; solve for b, c, d.
elements = ("Na", "H", "S", "O", "Cl")
atoms = {
    "NaHSO3": {"Na": 1, "H": 1, "S": 1, "O": 3},
    "HCl":    {"H": 1, "Cl": 1},
    "NaCl":   {"Na": 1, "Cl": 1},
    "SO2":    {"S": 1, "O": 2},
    "H2O":    {"H": 2, "O": 1},
}
unknowns = ("HCl", "NaCl", "SO2")
fixed = {"NaHSO3": Fraction(1), "H2O": Fraction(1)}

# Reactant contributions are positive and product contributions negative.
sign = {"NaHSO3": 1, "HCl": 1, "NaCl": -1, "SO2": -1, "H2O": -1}
matrix = []
for element in elements:
    row = [Fraction(sign[name] * atoms[name].get(element, 0))
           for name in unknowns]
    fixed_sum = sum(
        (Fraction(sign[name] * atoms[name].get(element, 0)) * amount
         for name, amount in fixed.items()),
        Fraction(0),
    )
    matrix.append(row + [-fixed_sum])

# Exact Gauss-Jordan elimination; also checks consistency and uniqueness.
pivot_row = 0
pivots = []
for col in range(len(unknowns)):
    pivot = next((r for r in range(pivot_row, len(matrix))
                  if matrix[r][col]), None)
    if pivot is None:
        continue
    matrix[pivot_row], matrix[pivot] = matrix[pivot], matrix[pivot_row]
    scale = matrix[pivot_row][col]
    matrix[pivot_row] = [x / scale for x in matrix[pivot_row]]
    for r in range(len(matrix)):
        if r != pivot_row and matrix[r][col]:
            factor = matrix[r][col]
            matrix[r] = [x - factor * y
                          for x, y in zip(matrix[r], matrix[pivot_row])]
    pivots.append(col)
    pivot_row += 1

if any(not any(row[:-1]) and row[-1] for row in matrix):
    raise ArithmeticError("Atom-balance equations are inconsistent")
if len(pivots) != len(unknowns):
    print("UNSUPPORTED")
    raise SystemExit

solution = {unknowns[col]: matrix[r][-1] for r, col in enumerate(pivots)}
coefficients = {**fixed, **solution}

# Confirm every element balances and all reaction coefficients are positive.
for element in elements:
    balance = sum(
        (Fraction(sign[name] * atoms[name].get(element, 0)) * amount
         for name, amount in coefficients.items()),
        Fraction(0),
    )
    if balance != 0:
        raise ArithmeticError("Balance verification failed")
if any(value <= 0 for value in coefficients.values()):
    raise ArithmeticError("Nonpositive reaction coefficient")

acid_moles = solution["HCl"]
answer = (str(acid_moles.numerator) if acid_moles.denominator == 1
          else f"{acid_moles.numerator}/{acid_moles.denominator}")

print(json.dumps({
    "final_answer": f"{answer} mole",
    "evidence": {
        "balanced_coefficients": {
            name: str(coefficients[name])
            for name in ("NaHSO3", "HCl", "NaCl", "SO2", "H2O")
        },
        "atom_balance_verified": True
    }
}))
