terms = [(1, -24), (1, -20), (-2, 44)]
solutions = []
evidence = []

for lo, hi, sample in pieces:
    a = Fraction(0)
    b = Fraction(0)
    for coeff, constant in terms:
        sign = 1 if coeff * sample + constant > 0 else -1
        a += sign * coeff
        b += sign * constant

    domain = (
        f"({ '-inf' if lo is None else lo }, "
        f"{ 'inf' if hi is None else hi })"
    )

    if a == 0:
        if b == 0:
            solutions.append((lo, hi))
            zero = "whole piece"
        else:
            zero = "none"
    else:
        root = -b / a
        if (lo is None or root >= lo) and (hi is None or root <= hi):
            solutions.append((root, root))
            zero = str(root)
        else:
            zero = "none"

    evidence.append({
        "piece": domain,
        "affine": f"{a}*x+{b}",
        "zeros": zero,
    })

# Merge overlapping or adjoining closed solution intervals.
solutions.sort(key=lambda interval: Fraction("-1000000000000000000")
               if interval[0] is None else interval[0])
merged = []
for lo, hi in solutions:
    if not merged:
        merged.append([lo, hi])
        continue
    prev_lo, prev_hi = merged[-1]
    if prev_hi is None or lo is None or lo <= prev_hi:
        merged[-1][1] = None if prev_hi is None or hi is None else max(prev_hi, hi)
    else:
        merged.append([lo, hi])

def show(q):
    return str(q.numerator) if q.denominator == 1 else f"{q.numerator}/{q.denominator}"

answer_parts = []
for lo, hi in merged:
    left = "-∞" if lo is None else show(lo)
    right = "∞" if hi is None else show(hi)
    left_bracket = "(" if lo is None else "["
    right_bracket = ")" if hi is None else "]"
    answer_parts.append(f"{left_bracket}{left}, {right}{right_bracket}")

