    if op == ":":
        return colon(a, b)
    if op == "><":
        return a * b if colon(a, b) > 0 else (-a) * (-b)
    if op == "~":
        g = gcd(a, b)
        return a - b if g == 1 else g
    if op == "!":
        return min(a, b) if is_prime(a) or is_prime(b) else max(a, b)
    if op == "#":
        return a - b if apply("~", a, b) > 0 else colon(a, b)
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    raise ValueError(f"Unknown operator: {op}")

def evaluate(text):
    ts = re.findall(r"><|[A-Za-z]+|\d+|[()+*:#~!-]", text)
    i = 0
    binary_ops = {"><", ":", "~", "!", "#", "+", "-", "*"}

    def atom():
        nonlocal i
        if i >= len(ts):
            raise ValueError("Unexpected end of expression")
        if ts[i] == "-":
            i += 1
            return -atom()
        if ts[i] == "(":
            i += 1
            value = expr()
            if i >= len(ts) or ts[i] != ")":
                raise ValueError("Missing closing parenthesis")
            i += 1
            return value
        token = ts[i]
        i += 1
        return int(token) if token.isdigit() else words[token]

    def expr():
        nonlocal i
        value = atom()
        while i < len(ts) and ts[i] in binary_ops:
            op = ts[i]
            i += 1
            value = apply(op, value, atom())
        return value

    result = expr()
    if i != len(ts):
        raise ValueError("Unparsed tokens")
    return result

