    if op == "-":
        return a - b
    if op == "*":
        return a * b
    raise ValueError("unknown operator")

TOKEN_RE = re.compile(r"\s*(><|[()+\-*:~#!]|[0-9]+|[A-Za-z]+)")

def evaluate(text):
    tokens = []
    pos = 0
    while pos < len(text):
        match = TOKEN_RE.match(text, pos)
        if not match:
            if text[pos:].strip() == "":
                break
            raise ValueError("unrecognized token")
        tokens.append(match.group(1))
        pos = match.end()

    index = 0
    precedence = {
        "+": 10, "-": 10,
        "*": 20,
        ":": 30, "><": 30, "~": 30, "!": 30, "#": 30,
    }

    def parse_expr(min_precedence=0):
        nonlocal index
        if index >= len(tokens):
            raise ValueError("incomplete expression")

        token = tokens[index]
        index += 1

        if token in ("+", "-"):
            value = parse_expr(100)
            left = value if token == "+" else -value
        elif token == "(":
            left = parse_expr()
            if index >= len(tokens) or tokens[index] != ")":
                raise ValueError("unmatched parenthesis")
            index += 1
        elif token.isdigit():
            left = int(token)
        elif token in WORDS:
            left = WORDS[token]
