for n in range(1, order + 1):
    coefficient = sum(
        Fraction(k) * g[k] * a[n - k]
        for k in range(1, n + 1)
    ) / n
    a.append(coefficient)

# The linear coefficient of (f(x)-f(2x))/x is e*(a1-2*a1).
limit_coefficient = a[1] * (1 - 2)
assert a[1] == Fraction(-1, 2)
assert limit_coefficient == Fraction(1, 2)

