import math
import re

expressions = {
    "A": """((((-10 -! ten) - (-6 #<> 10)) #*- ((-1 # -2) ][][ (seven ! -7))) ][ (((-2 ! -10) -* (-8 ~!+ -7)) #* ((nine *!! -2) *+<> (eight <> -2))))""",
    "B": """((((-6 ][+ -3) - (-1 # -7)) -*<> ((-10 ! -6) <> (-6 : one))) * (((1 <> seven) -# (eight ][-* eight)) ][ ((-8 +:: 1) : (six #+ one))))""",
    "C": """((((2 ! -3) #- (-4 +:~ -5)) :*# ((4 -<> four) # (5 # 2))) <> (((8 : -10) ][:! (2 **<> -1)) ][ ((-6 +! -4) - (4 * eight))))""",
}

words = {
    "one": 1, "six": 6, "seven": 7, "eight": 8,
    "nine": 9, "ten": 10,
}
operator_tokens = {"+", "-", "*", "!", ":", "~", "#", "<>", "]["}
token_pattern = re.compile(r"<>|\]\[|-?\d+|[A-Za-z]+|[()+\-*!~#:]")


def tokenize(text):
    tokens = token_pattern.findall(text)
    if "".join(tokens).replace(" ", "") != re.sub(r"\s+", "", text):
        raise ValueError("Could not tokenize expression")
    return tokens


def prime(n):
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    d = 3
    while d * d <= n:
        if n % d == 0:
            return False
        d += 2
    return True


def apply(op, a, b):
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if op == "!":
        return a + b if a - b > 0 else a * b
    if op == ":":
        return a * b if a - b > 0 else (-a) * (-b)
    if op == "~":
        if abs(a - b) < 2:
            return apply(":", b, a) - b
        return apply(":", a, b) - a
    if op == "#":
        if b < 2:
            return apply("!", apply("~", a, a), b)
        return apply("!", apply("~", b, b), a)
    if op == "<>":
        g = math.gcd(a, b)
        return apply("#", a, b) if g == 1 else g
    if op == "][":
        return min(a, b) if prime(a) or prime(b) else max(a, b)
    raise ValueError("Unknown operator: " + op)


class Parser:
    def __init__(self, text):
        self.tokens = tokenize(text)
        self.pos = 0

    def atom(self):
        if self.pos >= len(self.tokens):
            raise ValueError("Expected an operand")
        token = self.tokens[self.pos]
        if token == "(":
            self.pos += 1
            value = self.expression()
            if self.pos >= len(self.tokens) or self.tokens[self.pos] != ")":
                raise ValueError("Unmatched parenthesis")
            self.pos += 1
            return value
        self.pos += 1
        if token in words:
            return words[token]
        return int(token)

    def expression(self):
        value = self.atom()
        while self.pos < len(self.tokens) and self.tokens[self.pos] != ")":
            if self.tokens[self.pos] not in operator_tokens:
                raise ValueError("Expected an operator")
            ops = []
            while self.pos < len(self.tokens) and self.tokens[self.pos] in operator_tokens:
                ops.append(self.tokens[self.pos])
                self.pos += 1
            rhs = self.atom()
            # In a op1 op2 b, apply both operators using the same b.
            for op in ops:
                value = apply(op, value, rhs)
        return value

    def parse(self):
        value = self.expression()
        if self.pos != len(self.tokens):
            raise ValueError("Unexpected trailing tokens")
        return value


values = {name: Parser(expr).parse() for name, expr in expressions.items()}
result = values["A"] + values["B"] - values["C"]

for name in ("A", "B", "C"):
    print(f"{name} = {values[name]}")
print(f"A + B - C = {result}")
print("CHECK FAIL: the submitted response gives no numerical answer.")
