import json
import math

WORDS = {
    "zero": 0, "one": 1, "two": 2, "three": 3, "four": 4,
    "five": 5, "six": 6, "seven": 7, "eight": 8, "nine": 9,
    "ten": 10,
}
OPS = set("+-*&#@!")

A_TEXT = "((((((((((((-6 @ six) -& 4) --& -6) @## one) *!# one) #& -3) -! -10) & -2) * 3) *@ four) & -3) *# 10)"
B_TEXT = "(((((((((((((((((((((-5 - 9) * three) -+ -9) #* -2) &!# one) # -7) -# -4) + two) +- -3) #*# -7) #& five) # -6) -&+ 4) @ -7) +!- -1) #*+ -3) -- 2) * two) @ 2) @- -2)"
C_TEXT = "((((((((((((-8 #*@ -9) !# eight) @ -4) ** -9) !+ 8) *@ -1) +!& 3) !-# five) +!! ten) - -6) @+@ one) & 5)"


def is_prime(n):
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    d = 3
    while d * d <= n:
        if n % d == 0:
            return False
        d += 2
    return True


def apply(op, a, b):
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if op in "&@":
        return a - b if a * b > 0 else a + b
    if op == "!":
        return min(a, b) if is_prime(a) or is_prime(b) else max(a, b)
    if op == "#":
        return apply("@", a, b) if math.gcd(a, b) == 1 else math.gcd(a, b)
    raise ValueError("Unknown operator")


class Parser:
    def __init__(self, text):
        self.text = text
        self.i = 0

    def skip_space(self):
        while self.i < len(self.text) and self.text[self.i].isspace():
            self.i += 1

    def atom(self):
        self.skip_space()
        if self.i >= len(self.text):
            raise ValueError("Expected operand")

        if self.text[self.i] == "(":
            self.i += 1
            value = self.expression()
            self.skip_space()
            if self.i >= len(self.text) or self.text[self.i] != ")":
                raise ValueError("Expected closing parenthesis")
            self.i += 1
            return value

        start = self.i
        if self.text[self.i] == "-":
            self.i += 1
        while self.i < len(self.text) and self.text[self.i].isdigit():
            self.i += 1
        if self.i > start and self.text[start:self.i] not in ("-", ""):
            return int(self.text[start:self.i])

        self.i = start
        while self.i < len(self.text) and self.text[self.i].isalpha():
            self.i += 1
        word = self.text[start:self.i]
        if word not in WORDS:
            raise ValueError("Unknown operand: " + word)
        return WORDS[word]

    def expression(self):
        value = self.atom()
        while True:
            self.skip_space()
            if self.i >= len(self.text) or self.text[self.i] == ")":
                return value

            ops = []
            while self.i < len(self.text) and self.text[self.i] in OPS:
                ops.append(self.text[self.i])
                self.i += 1
            if not ops:
                raise ValueError("Expected operator")

            rhs = self.atom()
            for op in ops:
                value = apply(op, value, rhs)


def evaluate(text):
    parser = Parser(text)
    result = parser.expression()
    parser.skip_space()
    if parser.i != len(text):
        raise ValueError("Unexpected trailing text")
    return result


A = evaluate(A_TEXT)
B = evaluate(B_TEXT)
C = evaluate(C_TEXT)
answer = A + B - C

print(json.dumps({
    "final_answer": str(answer),
    "evidence": {"A": A, "B": B, "C": C}
}))
