from itertools import permutations

bands = ("Uneasy", "Vegemite", "Wellspring", "Xpert", "Yardsign", "Zircon")
U, V, W, X, Y, Z = bands

def fixed_constraints(p):
    return p[V] < p[Z] and p[U] >= 4 and p[Y] <= 3

def original_constraint(p):
    return p[W] < p[X] and p[Z] < p[X]

def option_a(p):
    # No band other than Uneasy performs after Xpert.
    return all(p[b] < p[X] for b in bands if b != U)

def option_b(p):
    return p[V] < p[W] < p[Z]

def option_c(p):
    return p[V] < p[X] and p[W] < p[X]

def option_d(p):
    return abs(p[X] - p[U]) == 1

def option_e(p):
    return p[X] in (5, 6)

options = {
    "A": option_a,
    "B": option_b,
    "C": option_c,
    "D": option_d,
    "E": option_e,
}

universe = []
for order in permutations(bands):
    p = {band: slot for slot, band in enumerate(order, start=1)}
    if fixed_constraints(p):
        universe.append((order, p))

original_orders = {
    order for order, p in universe if original_constraint(p)
}
print("Orders satisfying the unchanged constraints:", len(universe))
print("Orders satisfying the original constraint as well:", len(original_orders))

equivalent = []
option_orders = {}
for label, condition in options.items():
    orders = {order for order, p in universe if condition(p)}
    option_orders[label] = orders
    diff = original_orders ^ orders
    print(f"Option {label}: {len(orders)} orders; symmetric difference = {len(diff)}")
    if not diff:
        equivalent.append(label)
    elif label == "E":
        witness = next(iter(orders - original_orders), None)
        if witness is not None:
            print("Option E counterexample (satisfies E and unchanged rules, not original):")
            print("  " + " < ".join(witness))
            p = {band: slot for slot, band in enumerate(witness, start=1)}
            print("  slots:", ", ".join(f"{band}={p[band]}" for band in bands))

print("Equivalent option(s):", ", ".join(equivalent) if equivalent else "none")
print("Submitted answer E:", "CHECK PASS" if "E" in equivalent else "CHECK FAIL")
print("Expected option A:", "CHECK PASS" if equivalent == ["A"] else "CHECK FAIL")
