            other_polarity != polarity and (other_rule, rule) in priority
            for other_rule, other_polarity in rule_supports
        )
        if not defeated:
            surviving.append((rule, polarity))
    return (
        any(polarity for _, polarity in surviving),
        any(not polarity for _, polarity in surviving),
