        if isinstance(node.op, ast.UAdd):
            return value
        raise ValueError("Unsupported unary operator")
    if isinstance(node, ast.BinOp):
        left, right = evaluate(node.left), evaluate(node.right)
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        if isinstance(node.op, ast.Div):
            return left / right
        raise ValueError("Unsupported arithmetic operator")
    if isinstance(node, ast.BoolOp):
        values = [evaluate(value) for value in node.values]
        if isinstance(node.op, ast.And):
            return all(values)
        if isinstance(node.op, ast.Or):
            return any(values)
        raise ValueError("Unsupported boolean operator")
    if isinstance(node, ast.Compare):
        left = evaluate(node.left)
        for op, comparator in zip(node.ops, node.comparators):
            right = evaluate(comparator)
            if isinstance(op, ast.LtE):
                result = left <= right
            elif isinstance(op, ast.Gt):
                result = left > right
            else:
                raise ValueError("Unsupported comparison")
            if not result:
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
        args = [evaluate(arg) for arg in node.args]
        if node.func.id == "max":
            return max(args)
        if node.func.id == "min":
            return min(args)
    raise ValueError("Unsupported expression")


def solve(text):
    for phrase, value in facts.items():
        text = text.replace(phrase, str(value))
    text = text.replace("is less than or equal to", "<=")
    text = text.replace("is greater than", ">")
    tree = ast.parse(text, mode="eval")
    return bool(evaluate(tree.body))


values = {letter: solve(text) for letter, text in expressions.items()}
true_options = [letter for letter, value in values.items() if value]
answer = true_options[0] if len(true_options) == 1 else "UNSUPPORTED"
print(json.dumps({"final_answer": answer, "evidence": {"truth_values": values}}))
