def substitute_t(p, value):
    out = {}
    for (pa, pb, pt), coefficient in p.items():
        monomial = (pa, pb)
        out[monomial] = out.get(monomial, Fraction(0)) + coefficient * value**pt
    return {m: c for m, c in out.items() if c}

