from fractions import Fraction

# Let s be a continuous separator with s=0 on A and s=1 on B.
# The proposed continuous function is g=(1-s)f1+s*f2.
# Verify its endpoint identities exactly as formal polynomials.

# Polynomials use exponent tuples (power of s, power of f1, power of f2).
def add(p, q):
    result = dict(p)
    for monomial, coefficient in q.items():
        result[monomial] = result.get(monomial, Fraction(0)) + coefficient
        if result[monomial] == 0:
            del result[monomial]
    return result

def multiply(p, q):
    result = {}
    for m1, c1 in p.items():
        for m2, c2 in q.items():
            monomial = tuple(a + b for a, b in zip(m1, m2))
            result[monomial] = result.get(monomial, Fraction(0)) + c1 * c2
    return {m: c for m, c in result.items() if c != 0}

def substitute_s(p, value):
    result = {}
    for (power_s, power_f1, power_f2), coefficient in p.items():
        monomial = (power_f1, power_f2)
        result[monomial] = (
            result.get(monomial, Fraction(0))
            + coefficient * value**power_s
        )
    return {m: c for m, c in result.items() if c != 0}

s  = {(1, 0, 0): Fraction(1)}
f1 = {(0, 1, 0): Fraction(1)}
f2 = {(0, 0, 1): Fraction(1)}
one = {(0, 0, 0): Fraction(1)}

g = add(multiply(add(one, {(1, 0, 0): Fraction(-1)}), f1),
        multiply(s, f2))

on_a = substitute_s(g, Fraction(0))
on_b = substitute_s(g, Fraction(1))

assert on_a == {(1, 0): Fraction(1)}
assert on_b == {(0, 1): Fraction(1)}

print("Construction: g=(1-s)f1+s*f2, where s=0 on A and s=1 on B.")
print("Exact substitution checks: g|A=f1 and g|B=f2.")
print("Continuity follows from continuity of s, f1, f2 and the arithmetic operations.")
print("The submitted answer 'yes' is correct.")
print("CHECK PASS")
