    "opinion", "size", "age", "shape",
    "color", "origin", "material", "purpose"
)

# Category sequences in the givens that constrain adjective order.
observed = [
    ("origin", "size"),                 # e.g. japanese medium-size
    ("color", "age"),                   # e.g. green archaic
    ("shape", "purpose"),               # e.g. pyramidal eating
    ("opinion", "material"),            # e.g. terrible iron
    ("size", "color", "purpose"),       # massive black exercise
    ("origin", "age", "shape"),         # german brand-new spherical
]

options = {
    "A": ("opinion", "material", "color", "age", "shape", "purpose"),
    "B": ("color", "age", "shape", "purpose", "material", "opinion"),
    "C": ("size", "color", "age", "shape", "purpose", "material", "opinion"),
    "D": ("origin", "size", "color", "age", "shape", "purpose",
          "material", "opinion"),
    "E": ("material", "opinion", "color", "age", "shape", "purpose", "size"),
    "F": ("material", "opinion", "color", "age", "shape", "purpose",
          "size", "origin"),
    "G": ("opinion", "color", "age", "shape", "purpose", "size", "origin"),
    "H": ("origin", "size", "color", "age", "shape", "purpose",
          "opinion", "material"),
    "I": ("material", "color", "age", "shape", "purpose", "size", "origin"),
    "J": ("origin", "size", "color", "age", "shape", "purpose"),
}

def respects(order, sequence):
    rank = {category: i for i, category in enumerate(order)}
    return all(rank[a] < rank[b]
               for a, b in zip(sequence, sequence[1:]))

models = [
    order for order in itertools.permutations(categories)
    if all(respects(order, sequence) for sequence in observed)
]

def correct_choices(order):
    correct = [label for label, sequence in options.items()
               if respects(order, sequence)]
    return "".join(correct) if correct else "K"

answers = {}
witnesses = {}
for order in models:
    answer = correct_choices(order)
    answers[answer] = answers.get(answer, 0) + 1
    witnesses.setdefault(answer, order)

if len(answers) == 1:
    final_answer = next(iter(answers))
else:
    final_answer = "UNSUPPORTED"

evidence = {
    "consistent_orders": len(models),
    "possible_choice_sets": answers,
}
if len(answers) > 1:
    evidence["witnesses"] = {
        answer: list(order) for answer, order in witnesses.items()
    }

print(json.dumps(
    {"final_answer": final_answer, "evidence": evidence},
    separators=(",", ":")
))
