        changed |= add(("not_invests_in_company_owned_by", "ostrich", "shark"))

    # Rule 2: Chihuahua watches a movie released after Facebook was founded.
    if (
        ("watches_movie_year", "chihuahua", 2010) in facts
        and movie_is_after_facebook_founding
    ):
        changed |= add(("hides_cards_from", "chihuahua", "shark"))

    # Rule 4: investing in a fangtooth-owned company -> pays the badger.
    for predicate, animal, owner in tuple(facts):
        if predicate == "invests_in_company_owned_by" and owner == "fangtooth":
            changed |= add(("pays_money_to", animal, "badger"))

    # Rule 6: an ostrich card in a rainbow color -> does not invest
    # in a company owned by the shark.
    for predicate, animal, color in tuple(facts):
        if (
            predicate == "has_card_color"
            and animal == "ostrich"
            and color in rainbow_colors
        ):
            changed |= add(
                ("not_invests_in_company_owned_by", "ostrich", "shark")
            )

    # Rule 7: shark younger than 18 months -> acquires swallow photo.
    for predicate, animal, age_months in tuple(facts):
        if predicate == "age_months" and animal == "shark" and age_months < 18:
            changed |= add(("acquires_photo_of", "shark", "swallow"))

    # Rule 8: paying the badger -> smiles at the basenji.
    for predicate, animal, recipient in tuple(facts):
        if predicate == "pays_money_to" and recipient == "badger":
            changed |= add(("smiles_at", animal, "basenji"))

    # Rule 9: shark has more than 10 friends -> acquires swallow photo.
    for predicate, animal, count in tuple(facts):
        if predicate == "friends_count" and animal == "shark" and count > 10:
            changed |= add(("acquires_photo_of", "shark", "swallow"))

    # Rule 5: both stated conditions -> shark disarms the zebra.
    if (
        ("hides_cards_from", "chihuahua", "shark") in facts
        and ("not_invests_in_company_owned_by", "ostrich", "shark") in facts
    ):
        changed |= add(("disarms", "shark", "zebra"))

    # Rule 3: smiling at the basenji and disarming the zebra -> does not dance.
    animals = {
        animal for predicate, animal, target in facts
        if predicate == "smiles_at" and target == "basenji"
    }
    for animal in animals:
        if ("disarms", animal, "zebra") in facts:
            changed |= add(("not_dances_with", animal, "dugong"))

positive = ("dances_with", "shark", "dugong")
negative = ("not_dances_with", "shark", "dugong")

if positive in facts and negative not in facts:
    answer = "proved"
elif negative in facts and positive not in facts:
