else:
    answer = "unknown"

relevant = [
    ("invests_in_company_owned_by", "shark", "fangtooth"),
    ("pays_money_to", "shark", "badger"),
    ("smiles_at", "shark", "basenji"),
    ("hides_cards_from", "chihuahua", "shark"),
