models = []
counterexample = None
for values in itertools.product((False, True), repeat=len(atoms)):
    v = dict(zip(atoms, values))
    if satisfies_premises(v):
        models.append(v)
        if not conclusion(v) and counterexample is None:
            counterexample = v

entailed = counterexample is None
