def linear_extensions(remaining, placed):
    if not remaining:
        yield tuple(placed)
        return
    available = sorted(
        node for node in remaining
        if all(right != node or left in placed for left, right in edges)
    )
    for node in available:
        yield from linear_extensions(remaining - {node}, placed + [node])

