import itertools
import json

# Literal predicate model:
# Ath = athlete, Meet = participates, Strong = strong,
# Rare = seldom gets sick, Unwell = not well enough, Sick = actually sick.
names = ("Ath", "Meet", "Strong", "Rare", "Unwell", "Sick")
domain = range(2)
satisfying = []
countermodels = {option: None for option in ("A", "C", "D")}
sick_participant_model = None

for bits in itertools.product((False, True), repeat=len(names) * len(domain)):
    predicates = {
        name: {x: bits[i * len(domain) + x] for x in domain}
        for i, name in enumerate(names)
    }

    # Premises: meeting athletes are strong; strong athletes are rarely sick;
    # some unwell athlete is unable to participate.
    if any(predicates["Meet"][x] and not predicates["Ath"][x]
           for x in domain):
        continue
    if any(predicates["Meet"][x] and not predicates["Strong"][x]
           for x in domain):
        continue
    if any(predicates["Strong"][x] and not predicates["Rare"][x]
           for x in domain):
        continue
    if not any(predicates["Ath"][x] and predicates["Unwell"][x]
               and not predicates["Meet"][x] for x in domain):
        continue

    satisfying.append(predicates)

    # A and C both assert the same intersection in this literal model.
    rare_and_unwell = any(
        predicates["Ath"][x] and predicates["Unwell"][x]
        and predicates["Rare"][x] for x in domain
    )
    strong_and_unwell = any(
        predicates["Strong"][x] and predicates["Unwell"][x]
        for x in domain
    )
    for option, conclusion in (("A", rare_and_unwell),
                               ("C", rare_and_unwell),
                               ("D", strong_and_unwell)):
        if not conclusion and countermodels[option] is None:
            countermodels[option] = {
                name: [x for x in domain if predicates[name][x]]
                for name in names
            }

    if sick_participant_model is None and any(
        predicates["Meet"][x] and predicates["Sick"][x] for x in domain
    ):
        sick_participant_model = {
            name: [x for x in domain if predicates[name][x]]
            for name in names
        }

# "Very few" has no specified formal threshold, and the premises do not
# connect being "rarely sick" with the predicate "actually sick".
result = {
    "final_answer": "UNSUPPORTED",
    "evidence": {
        "finite_models_satisfying_premises": len(satisfying),
        "countermodels_to": [
            option for option, model in countermodels.items()
            if model is not None
        ],
        "countermodels": countermodels,
        "B_status": "undefined quantitative phrase; actual sickness is unconstrained",
        "participant_sick_witness": sick_participant_model,
    },
}
print(json.dumps(result, separators=(",", ":")))
