def normalize(text):
    def replace_capital(match):
        country, city = match.group(1), match.group(2)
        key = (country, city)
        if key not in capitals:
            raise ValueError(f"Unknown capital claim: {country}, {city}")
        return str(capitals[key])

    text = re.sub(
        r"The capital of (?:the )?([A-Za-z]+) is ([A-Za-z]+)\.",
        replace_capital,
        text,
    )
    for phrase, operator in (
        ("is less than or equal to", "<="),
        ("is greater than or equal to", ">="),
        ("is less than", "<"),
        ("is greater than", ">"),
    ):
        text = text.replace(phrase, operator)
    return text

def evaluate(node):
    if isinstance(node, ast.Constant):
        if isinstance(node.value, bool):
            return node.value
        if isinstance(node.value, int):
            return Fraction(node.value)
        raise ValueError(f"Unsupported constant: {node.value!r}")

    if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.Not):
        return not evaluate(node.operand)

    if isinstance(node, ast.BoolOp):
        if isinstance(node.op, ast.And):
            for value in node.values:
                if not evaluate(value):
                    return False
            return True
        if isinstance(node.op, ast.Or):
            for value in node.values:
                if evaluate(value):
                    return True
            return False

    if isinstance(node, ast.BinOp):
        left, right = evaluate(node.left), evaluate(node.right)
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        if isinstance(node.op, ast.Div):
            return left / right

    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
        args = [evaluate(arg) for arg in node.args]
        if node.func.id == "max":
            return max(args)
        if node.func.id == "min":
            return min(args)

    if isinstance(node, ast.Compare):
        left = evaluate(node.left)
        for op, comparator in zip(node.ops, node.comparators):
            right = evaluate(comparator)
            if isinstance(op, ast.Gt):
                okay = left > right
            elif isinstance(op, ast.GtE):
                okay = left >= right
            elif isinstance(op, ast.Lt):
                okay = left < right
            elif isinstance(op, ast.LtE):
                okay = left <= right
            elif isinstance(op, ast.Eq):
                okay = left == right
            elif isinstance(op, ast.NotEq):
                okay = left != right
            else:
                raise ValueError(f"Unsupported comparison: {type(op).__name__}")
            if not okay:
                return False
            left = right
        return True

    raise ValueError(f"Unsupported syntax: {ast.dump(node)}")

results = {}
for label, expression in expressions.items():
