from itertools import product

# Formalization: the domain is all athletes. P = participates, S = strong,
# R = "seldom gets sick", U = unwell. "Some athletes are not well enough
# to take part" is represented by exists(U and not P).
#
# Under this formalization A and C both say exists(U and R); their wording
# differs only in the order of the same two properties.

P, S, R, U = 1, 2, 4, 8

def has(state, bit):
    return bool(state & bit)

def satisfies_premises(states):
    return (
        all(not has(x, P) or has(x, S) for x in states)
        and all(not has(x, S) or has(x, R) for x in states)
        and any(has(x, U) and not has(x, P) for x in states)
    )

def option_A(states):
    return any(has(x, U) and has(x, R) for x in states)

def option_C(states):
    return any(has(x, R) and has(x, U) for x in states)

def option_D(states):
    return any(has(x, S) and has(x, U) for x in states)

names = {0: "none", P: "participates", S: "strong",
         R: "seldom sick", U: "unwell"}

def describe(states):
    return [tuple(name for bit, name in names.items() if bit and has(x, bit))
            for x in states]

# Exhaustively enumerate small finite models. A countermodel alone suffices
# to establish non-entailment in ordinary first-order logic.
counts = {}
countermodels = {"A": None, "C": None, "D": None}
for n in (1, 2):
    count = 0
    for states in product(range(16), repeat=n):
        if not satisfies_premises(states):
            continue
        count += 1
        for label, option in (("A", option_A), ("C", option_C),
                              ("D", option_D)):
            if not option(states) and countermodels[label] is None:
                countermodels[label] = (n, states)
    counts[n] = count

print("Finite-model enumeration (domain sizes 1 and 2):")
for n, count in counts.items():
    print(f"  size {n}: {count} models satisfy the premises")

for label in ("A", "C", "D"):
    n, states = countermodels[label]
    print(f"Countermodel for option {label} (size {n}): {describe(states)}")

# A and C are equivalent under the stated translation, in every model.
assert all(option_A(states) == option_C(states)
           for n in (1, 2)
           for states in product(range(16), repeat=n))
print("A and C have identical truth conditions under this formalization.")

# "Very few" has no specified numerical threshold, and "seldom sick"
# does not by itself mean "not sick now." The premises therefore do not
# provide a precise test for B. For illustration, current sickness K can
# hold for every participant while all premises still hold.
# Rows below are (P, S, R, U, currently_sick).
illustrative_model = [
    (True, True, True, False, True),
    (True, True, True, False, True),
    (False, False, False, True, False),
]
assert all(not p or s for p, s, r, u, k in illustrative_model)
assert all(not s or r for p, s, r, u, k in illustrative_model)
assert any(u and not p for p, s, r, u, k in illustrative_model)
sick_participants = sum(p and k for p, s, r, u, k in illustrative_model)
print(f"Illustration for B: {sick_participants} currently sick participants "
      "is compatible with the premises; 'very few' is undefined.")

print("CHECK PASS: A is not derivable (an explicit countermodel exists).")
print("CHECK FAIL: A is not uniquely identified as the non-derivable option "
      "under this formalization; C is equivalent to A, and D also has a "
      "countermodel.")
print("UNSUPPORTED: B cannot be precisely evaluated without defining "
      "'very few' and how current sickness relates to 'seldom gets sick'.")
