        if "G" in day and "H" in day:
            return False

    # If K is on day 1, G must be on day 2.
    if "K" in days[0] and "G" not in days[1]:
        return False

    # If S is on day 3, H must be on day 2.
    if "S" in days[2] and "H" not in days[1]:
        return False

    return True

def option_values(days):
    together = lambda x, y: any(x in day and y in day for day in days)
    return {
        "A": together("G", "S"),
        "B": not together("S", "H"),
        "C": not together("K", "S"),
        "D": not together("K", "G"),
    }

def check_model(exactly_once):
    valid_schedules = []
    for days in product(pairs, repeat=3):
        if exactly_once and set().union(*days) != set(people):
            continue
        if valid(days):
            valid_schedules.append(days)

    label = "each person used exactly once" if exactly_once else "repeat assignments allowed"
    print(label + ":")
    print("  valid schedules:", len(valid_schedules))

    for option in "ABCD":
        counterexample = next(
            (days for days in valid_schedules if not option_values(days)[option]),
            None
        )
        print("  option", option, "must be true:", counterexample is None)
        if counterexample is not None:
            print("    counterexample:", counterexample)

    return valid_schedules

all_schedules = check_model(exactly_once=False)
check_model(exactly_once=True)

# The submitted answer is B. A counterexample in the literal model disproves it.
