from functools import lru_cache

# Exhaustively search for a tiling of a 6-by-6 square by L triominoes.
n = 6
full = (1 << (n * n)) - 1
placements = []

# Each L triomino is a 2-by-2 block with one corner omitted.
for r in range(n - 1):
    for c in range(n - 1):
        block = [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]
        for omitted in block:
            cells = [p for p in block if p != omitted]
            mask = sum(1 << (rr * n + cc) for rr, cc in cells)
            placements.append((mask, cells))

by_cell = [[] for _ in range(n * n)]
for mask, cells in placements:
    for r, c in cells:
        by_cell[r * n + c].append((mask, cells))

@lru_cache(None)
def tile(used):
    if used == full:
        return ()
    # The first uncovered cell must be covered by the next piece.
    first = next(i for i in range(n * n) if not (used >> i) & 1)
    for mask, cells in by_cell[first]:
        if not (used & mask):
            rest = tile(used | mask)
            if rest is not None:
                return (cells,) + rest
    return None

solution = tile(0)
if solution is None:
    print("No tiling found for side 6; this search does not settle the universal claim.")
    print("CHECK UNKNOWN")
else:
    board = [[0] * n for _ in range(n)]
    for label, cells in enumerate(solution, 1):
        for r, c in cells:
            assert board[r][c] == 0
            board[r][c] = label

    assert len(solution) == 12
    assert all(board[r][c] != 0 for r in range(n) for c in range(n))
    assert all(len(cells) == 3 for cells in solution)
    assert all(
        max(r for r, c in cells) - min(r for r, c in cells) == 1
        and max(c for r, c in cells) - min(c for r, c in cells) == 1
        and len({(r, c) for r, c in cells}) == 3
        for cells in solution
    )

    print("Exact tiling found: square side = 6, area = 36, L triominoes = 12.")
    for row in board:
        print(" ".join(f"{x:2d}" for x in row))
    print("This square is a counterexample to the submitted answer 'No'.")
    print("CHECK FAIL")
