# Use the normed algebra of 2x2 rational matrices with the max-row-sum norm.
I = ((1, 0), (0, 1))
N = ((0, 1), (0, 0))

def multiply(A, B):
    return tuple(
        tuple(sum(A[i][k] * B[k][j] for k in range(2)) for j in range(2))
        for i in range(2)
    )

def add(A, B):
    return tuple(tuple(A[i][j] + B[i][j] for j in range(2)) for i in range(2))

def negate(A):
    return tuple(tuple(-A[i][j] for j in range(2)) for i in range(2))

def norm(A):
    return max(sum(abs(v) for v in row) for row in A)

# Choose x=I and y=N-I, so x+y=N.
x = I
y = add(N, negate(I))
a = add(x, y)

assert a == N and norm(a) == 1
assert multiply(N, N) == ((0, 0), (0, 0))
assert multiply(I, I) == I

# Thus (x+y)^n=0 for every n>=2, while x^n=I for every n>=1.
nilpotent_tail_is_zero = multiply(a, a) == ((0, 0), (0, 0))
x_power_norm = norm(x)
answer = "No" if nilpotent_tail_is_zero and x_power_norm == 1 else "UNSUPPORTED"

