import itertools
import json

# Boolean atoms in the finite ground instance.
atoms = (
    "duck_suspects_butterfly",
    "duck_suspects_otter",
    "ant_does_not_hug_flamingo",
    "flamingo_reveals_secret_to_otter",
    "reindeer_hugs_crab",
    "otter_does_not_hide_cards",
    "otter_hides_cards",
)

fish_name = "Paco"
reindeer_name = "Peddi"
names_match = fish_name[0].casefold() == reindeer_name[0].casefold()

models = []
for values in itertools.product((False, True), repeat=len(atoms)):
    v = dict(zip(atoms, values))

    # Original game-state facts.
    if not v["duck_suspects_butterfly"]:
        continue
    if not v["ant_does_not_hug_flamingo"]:
        continue

    # Rule 1: matching initials imply that the reindeer hugs the crab.
    if names_match and not v["reindeer_hugs_crab"]:
        continue

    # Rule 2.
    if v["duck_suspects_butterfly"] and not v["duck_suspects_otter"]:
        continue

    # Rule 3.
    if v["ant_does_not_hug_flamingo"] and not v["flamingo_reveals_secret_to_otter"]:
        continue

    # Rule 4.
    if (
        v["flamingo_reveals_secret_to_otter"]
        and v["duck_suspects_otter"]
        and not v["otter_does_not_hide_cards"]
    ):
        continue

    # "Does not hide" is the negation of "hides."
    if v["otter_does_not_hide_cards"] == v["otter_hides_cards"]:
        continue

    models.append(v)

