from fractions import Fraction
from itertools import combinations

options = {
    "A": ["Schindler's List", "The Shawshank Redemption", "Braveheart",
          "Captain America The First Avenger", "Dances with Wolves"],
    "D": ["The Shawshank Redemption", "Pulp Fiction",
          "Captain America The First Avenger", "Schindler's List", "Manic"],
}

def pairwise_agreement(option, likes):
    pairs = list(combinations(options[option], 2))
    same = sum(likes[x] == likes[y] for x, y in pairs)
    return Fraction(same, len(pairs))

