import itertools
import json

# Adjective classes needed by the options.
categories = (
    "AGE", "MATERIAL", "OPINION", "ORIGIN",
    "ACTIVITY", "COLOR", "SHAPE", "SIZE",
)

# Precedence evidence taken from the accepted sentences in the problem.
# Every earlier class precedes every later class in each sentence.
evidence_sentences = [
    ("old paper earring", ["AGE", "MATERIAL"]),
    ("glass wonderful gray wallet", ["MATERIAL", "OPINION", "COLOR"]),
    ("silly russian banana", ["OPINION", "ORIGIN"]),
    ("archaic russian hiking chair", ["AGE", "ORIGIN", "ACTIVITY"]),
    ("whittling cyan key", ["ACTIVITY", "COLOR"]),
    ("triangular tiny dog", ["SHAPE", "SIZE"]),
]

edges = set()
for _, sequence in evidence_sentences:
    for i, earlier in enumerate(sequence):
        for later in sequence[i + 1:]:
            edges.add((earlier, later))

def adjective_class(word):
    word = word.lower()
    if word in {"old-fashioned", "ancient", "archaic", "old", "new",
                "brand-new"}:
        return "AGE"
    if word in {"steel", "plastic", "fiberglass", "wool", "cloth",
                "leather", "glass", "paper", "rubber", "wood"}:
        return "MATERIAL"
    if word in {"obnoxious", "awful", "repulsive", "ridiculous"}:
        return "OPINION"
    if word in {"nigerian", "iranian", "thai", "brazilian", "pakistani"}:
        return "ORIGIN"
    if word in {"walking", "drinking", "snorkeling", "whittling",
                "exercise", "eating"}:
        return "ACTIVITY"
    if word in {"indigo", "aqua", "violet", "blue", "magenta", "cyan",
                "yellow"}:
        return "COLOR"
    if word in {"pyramidal", "spherical", "rectangular", "circular"}:
        return "SHAPE"
    if word in {"medium-size", "midsize", "little", "small", "large",
                "enormous"}:
        return "SIZE"
    raise ValueError(f"Unclassified option adjective: {word}")

options = {
    "A": "obnoxious nigerian walking indigo pyramidal medium-size",
    "B": "little prismlike awful iranian smoking white",
    "C": "old steel obnoxious thai driving aqua",
    "D": "old-fashioned plastic obnoxious brazilian drinking violet "
         "midsize spherical",
    "E": "rectangular small ridiculous nigerian snorkeling blue "
         "fiberglass ancient",
    "F": "wool silly vietnamese whittling cyan square enormous",
    "G": "old cloth repulsive iranian snorkeling magenta medium-size",
    "H": "large rectangular ridiculous pakistani exercise indigo leather",
    "I": "circular ridiculous brazilian exercise yellow cloth brand-new",
    "J": "brand-new plastic repulsive brazilian eating violet "
         "prismlike midsize",
}

# Exhaustively enumerate the linear adjective orders compatible with the
# precedence constraints supplied by the examples.
orders = []
for order in itertools.permutations(categories):
    rank = {category: i for i, category in enumerate(order)}
    if all(rank[left] < rank[right] for left, right in edges):
        orders.append(order)

def valid_choices(order):
    rank = {category: i for i, category in enumerate(order)}
    valid = []
    for letter, phrase in options.items():
        sequence = [adjective_class(word) for word in phrase.split()]
        if all(rank[a] < rank[b] for a, b in zip(sequence, sequence[1:])):
            valid.append(letter)
    return "".join(valid)

by_answer = {}
for order in orders:
    answer = valid_choices(order)
    by_answer.setdefault(answer, order)

if len(by_answer) == 1:
    final_answer = next(iter(by_answer))
else:
    final_answer = "UNSUPPORTED"

witnesses = [
    {"order": list(order), "choices": answer}
    for answer, order in list(by_answer.items())[:2]
]

print(json.dumps({
    "final_answer": final_answer,
    "evidence": {
        "compatible_orders_exhaustively_checked": len(orders),
        "distinct_choice_sets": len(by_answer),
        "witnesses": witnesses,
        "unresolved_class_pair": ["COLOR", "SHAPE"],
    },
}, separators=(",", ":")))
